// Erasure coding: XOR parity lets any single lost block be rebuilt
const blocks=[10, 20, 30, 40];
const parity=blocks.reduce((a,b)=>a^b,0);
const lost=1;
const recovered=blocks.filter((_,i)=>i!==lost).reduce((a,b)=>a^b,0)^parity;
console.log('parity='+parity+', block['+lost+'] recovered='+recovered+' (original '+blocks[lost]+')');

